/* Example illustrating the concept (requires a linker and object files);  This is a conceptual representation */
#include <stdio.h>
extern int global_var; // Declared in another file
void func_a() {
   printf("Value of global_var in func_a: %d\n", global_var);
}
int main() {
   func_a();
   return 0;
}
/* Another file (e.g., 'other.c'): */
int global_var = 10;
/* Compile both files separately, then link to create executable: */
/* gcc -c main.c other.c */
/* gcc main.o other.o -o myprogram */
